   275	sub notify_result {
   276	    my ($self, $summary, $body) = @_;
   277	    return if !defined($ENV{DBUS_SESSION_BUS_ADDRESS}) || !length($ENV{DBUS_SESSION_BUS_ADDRESS});
   278	    my $notify = eval { $self->command_path('notify-send') };
   279	    return if !$notify;
   280	    my $pid = fork();
   281	    return if !defined $pid;
   282	    if ($pid == 0) {
   283	        open STDOUT, '>', '/dev/null' or POSIX::_exit(0);
   284	        open STDERR, '>&', \*STDOUT or POSIX::_exit(0);
   285	        my $executed = exec { $notify } $notify, '-a', 'Digital Assets', '-u', 'normal',
   286	            '-i', 'document-save', '-c', 'x-labwc.maintenance', '-t', '10000',
   287	            $summary, $body;
   288	        POSIX::_exit($executed ? 0 : 127);
   289	    }
   290	    waitpid($pid, 0);
   291	}
