   337	sub validate_user_file {
   338	    my ($self, $kind, $requested_path) = @_;
   339	    _safe_absolute_path('selected path', $requested_path);
   340	    $requested_path !~ /[\r\n]/ or _fatal('selected path cannot contain newlines');
   341	    !-l $requested_path && -f $requested_path && -r $requested_path
   342	        or _fatal('selected path must be a readable non-symbolic regular file');
   343	    my $resolved = abs_path($requested_path);
   344	    defined($resolved) && $resolved eq $requested_path
   345	        or _fatal('selected file must already be canonical');
   346	    index($resolved, $self->home() . '/') == 0
   347	        or _fatal('selected file must be inside the logged-in user home directory');
   348	    $self->_validate_extension($kind, $resolved);
   349	    my @stat = lstat $resolved;
   350	    $stat[4] == $< or _fatal('selected file must be owned by the active user');
   351	    ($stat[2] & 0022) == 0
   352	        or _fatal('selected file cannot be writable by group or other users');
   353	    $stat[7] > 0 && $stat[7] <= $self->max_input_bytes()
   354	        or _fatal('selected file is empty or exceeds the safety size limit');
   355	    return $resolved;
   356	}
