   358	sub _validate_extension {
   359	    my ($self, $kind, $path) = @_;
   360	    my %patterns = (
   361	        docx     => qr/\.docx\z/i,
   362	        pdf      => qr/\.pdf\z/i,
   363	        markdown => qr/\.(?:md|markdown|mdown|mkdn)\z/i,
   364	        image    => qr/\.(?:avif|bmp|gif|heic|jpe?g|png|tiff?|webp)\z/i,
   365	    );
   366	    exists $patterns{$kind} && $path =~ $patterns{$kind}
   367	        or _fatal("selected file does not have a supported $kind extension");
   368	}
