   370	sub read_input_list {
   371	    my ($self, $kind, $list_path) = @_;
   372	    my $runtime = $self->runtime_directory();
   373	    $list_path =~ /\A\Q$runtime\E\/labwc-digital-assets-list\.[A-Za-z0-9]+\z/
   374	        or _fatal('selection list is outside the managed runtime directory');
   375	    -f $list_path && !-l $list_path
   376	        or _fatal('selection list is not a regular file');
   377	    my @stat = lstat $list_path;
   378	    $stat[4] == $< && ($stat[2] & 07777) == 0600
   379	        or _fatal('selection list ownership or mode is unsafe');
   380	    $stat[7] <= 16_384 or _fatal('selection list exceeds the managed size limit');
   381	    open my $fh, '<:encoding(UTF-8)', $list_path
   382	        or _fatal("cannot read selection list: $!");
   383	    my @files;
   384	    while (my $line = <$fh>) {
   385	        $line =~ s/\r?\n\z//;
   386	        push @files, $self->validate_user_file($kind, $line);
   387	        @files <= $self->max_multi_files()
   388	            or _fatal('too many files in managed selection list');
   389	    }
   390	    close $fh or _fatal("cannot close selection list: $!");
   391	    @files >= 2 or _fatal('select at least two input files');
   392	    return \@files;
   393	}
