   395	sub pdf_page_count {
   396	    my ($self, $path) = @_;
   397	    my $pdfinfo = $self->command_path('pdfinfo');
   398	    my $output = $self->capture_timed(65_536, $pdfinfo, $path);
   399	    my ($pages) = $output =~ /^Pages:\s*([0-9]+)\s*$/m;
   400	    defined($pages) && $pages >= 1 && $pages <= $self->max_pdf_pages()
   401	        or _fatal('unable to determine a supported PDF page count');
   402	    return int($pages);
   403	}
   404	
   405	sub validate_page_range {
   406	    my ($self, $range, $total_pages) = @_;
   407	    $range =~ /\A[0-9]+(?:-[0-9]+)?(?:,[0-9]+(?:-[0-9]+)?)*\z/
   408	        or _fatal('page range must be a comma-separated list such as 1-3,5');
   409	    for my $part (split /,/, $range) {
   410	        my ($first, $last) = split /-/, $part, 2;
   411	        $last //= $first;
   412	        $first >= 1 && $last >= $first && $last <= $total_pages
   413	            or _fatal('page range contains a page outside the source PDF');
   414	    }
   415	    return $range;
   416	}
   417	
   418	sub prompt_page_range {
   419	    my ($self, $total_pages) = @_;
   420	    return $self->validate_page_range(
   421	        $self->prompt_line("Pages (1-$total_pages, for example 1-3,5): "),
   422	        $total_pages,
   423	    );
   424	}
   425	
   426	sub directory_has_file {
   427	    my ($self, $directory, $expression) = @_;
   428	    opendir my $dh, $directory or _fatal("cannot inspect output directory: $!");
   429	    while (my $entry = readdir $dh) {
   430	        next if $entry eq '.' || $entry eq '..';
   431	        my $path = "$directory/$entry";
   432	        if (-f $path && !-l $path && $entry =~ $expression) {
   433	            closedir $dh;
   434	            return 1;
   435	        }
   436	    }
   437	    closedir $dh or _fatal("cannot close output directory: $!");
   438	    return 0;
   439	}
