    19	sub _validate_runtime_arguments {
    20	    my ($self, @arguments) = @_;
    21	    @arguments >= 1 or die "labwc-digital-assets-action: missing Digital Assets action\n";
    22	    my $action = $self->policy()->assert_action(shift @arguments);
    23	    @arguments >= 1 or die "labwc-digital-assets-action: action requires a file or managed selection list\n";
    24	    for my $argument (@arguments) {
    25	        defined($argument) && length($argument) <= 4096 && $argument !~ /[\0\r\n]/
    26	            or die "labwc-digital-assets-action: unsafe action argument\n";
    27	    }
    28	    return ($action, @arguments);
    29	}
