    31	sub run {
    32	    my ($self, @argv) = @_;
    33	    $self->session()->assert_desktop_user();
    34	    my $run_in_terminal = @argv && $argv[0] eq '--run';
    35	    shift @argv if $run_in_terminal;
    36	    my ($action, @arguments) = $self->_validate_runtime_arguments(@argv);
    37	    if ($run_in_terminal) {
    38	        log_msg('info', "running Digital Assets action: $action");
