    42	        or die "labwc-digital-assets-action: labwc-terminal is unavailable\n";
    43	    log_msg('info', "opening Digital Assets action terminal: $action");
    44	    exec { $self->terminal() } $self->terminal(), '-e', '/usr/local/bin/labwc-digital-assets-action', '--run', $action, @arguments
    45	        or die "labwc-digital-assets-action: cannot open action terminal: $!\n";
