payload.arguments:
{"cmd":"set -Eeuo pipefail
export LC_ALL=C TZ=UTC
tmpdir=$(mktemp -d /tmp/labwc-perl-audit.XXXXXX)
case "$tmpdir" in
  /tmp/labwc-perl-audit.*) ;;
  *) printf '%s\n' 'refusing unexpected temporary directory' >&2; exit 1 ;;
esac
cleanup() {
  rm -rf -- "$tmpdir"
}
trap cleanup EXIT HUP INT TERM

mkdir -p "$tmpdir/stubs/MooX" "$tmpdir/stubs/Types" "$tmpdir/lib"
cat >"$tmpdir/stubs/Moo.pm" <<'PERL'
package Moo;
use strict;
use warnings;

our %ATTRIBUTES;

sub import {
    my ($class) = @_;
    my $target = caller;

    no strict 'refs';
    no warnings 'redefine';

    *{"${target}::has"} = sub {
        my ($name, %options) = @_;
        $ATTRIBUTES{$target}{$name} = \%options;

        *{"${target}::${name}"} = sub {
            my ($self, @arguments) = @_;
            if (@arguments) {
                $self->{$name} = $arguments[0];
                return $self->{$name};
            }
            return $self->{$name} if exists $self->{$name};

            my $value;
            if (exists $options{builder}) {
                $value = ref($options{builder}) eq 'CODE'
                    ? $options{builder}->($self)
                    : $self->$options{builder}();
            }
            elsif (exists $options{default}) {
                $value = ref($options{default}) eq 'CODE'
                    ? $options{default}->($self)
                    : $options{default};
            }
            $self->{$name} = $value;
            return $value;
        };
    };

    *{"${target}::new"} = sub {
        my ($package, @arguments) = @_;
        die "new expects key/value arguments\n" if @arguments % 2;
        return bless { @arguments }, $package;
    } unless defined &{"${target}::new"};

    return;
}

1;
PERL
cat >"$tmpdir/stubs/MooX/StrictConstructor.pm" <<'PERL'
package MooX::StrictConstructor;
use strict;
use warnings;
sub import { return; }
1;
PERL
cat >"$tmpdir/stubs/MooX/TypeTiny.pm" <<'PERL'
package MooX::TypeTiny;
use strict;
use warnings;
sub import { return; }
1;
PERL
cat >"$tmpdir/stubs/Types/Standard.pm" <<'PERL'
package Types::Standard;
use strict;
use warnings;

sub import {
    my ($class, @symbols) = @_;
    my $target = caller;
    no strict 'refs';
    no warnings 'redefine';
    for my $symbol (@symbols) {
        *{"${target}::${symbol}"} = sub { return $symbol; };
    }
    return;
}

1;
PERL

for library in \
  labwc-adb \
  digital-assets \
  labwc-network-control-action \
  labwc-network-scan-action \
  labwc-security-action; do
  cp -R -- "d-i/forky/hooks/role/desktop/target/usr/local/lib/perl5/site_perl/${library}" "$tmpdir/lib/${library}"
done
sed 's/__INSTALLER_ACCOUNT_USERNAME__/installer-audit/g' \
  "$tmpdir/lib/labwc-network-scan-action/LabwcNetworkScanAction/Root.pm.tmpl" \
  >"$tmpdir/lib/labwc-network-scan-action/LabwcNetworkScanAction/Root.pm"

perl5lib=$(printf '%s:' \
  "$tmpdir/stubs" \
  "$tmpdir/lib/labwc-adb" \
  "$tmpdir/lib/digital-assets" \
  "$tmpdir/lib/labwc-network-control-action" \
  "$tmpdir/lib/labwc-network-scan-action" \
  "$tmpdir/lib/labwc-security-action")
perl5lib=${perl5lib%:}

module_count=0
while IFS= read -r module; do
  PERL5LIB="$perl5lib" /usr/bin/perl -c -- "$module" >/dev/null
  ((module_count += 1))
done < <(find "$tmpdir/lib" -type f -name '*.pm' -print | LC_ALL=C sort)

entrypoint_count=0
for entrypoint in \
  d-i/forky/hooks/role/desktop/target/usr/local/bin/labwc-adb-action \
  d-i/forky/hooks/role/desktop/target/usr/local/bin/labwc-network-control-action \
  d-i/forky/hooks/role/desktop/target/usr/local/bin/labwc-network-scan-action \
  d-i/forky/hooks/role/desktop/target/usr/local/bin/labwc-security-action \
  d-i/forky/hooks/role/desktop/target/usr/local/libexec/labwc-network-control-action-root \
  "$tmpdir/lib/labwc-network-scan-action-root" \
  d-i/forky/hooks/role/desktop/target/usr/local/libexec/labwc-security-action-root; do
  if [[ "$entrypoint" == "$tmpdir/lib/labwc-network-scan-action-root" ]]; then
    sed 's#use lib '\''/usr/local/lib/perl5/site_perl/labwc-network-scan-action'\'';#use lib '\''/usr/local/lib/perl5/site_perl/labwc-network-scan-action'\'';#' \
      d-i/forky/hooks/role/desktop/target/usr/local/libexec/labwc-network-scan-action-root.tmpl \
      >"$entrypoint"
    chmod 0755 -- "$entrypoint"
  fi
  PERL5LIB="$perl5lib" /usr/bin/perl -c -- "$entrypoint" >/dev/null
  ((entrypoint_count += 1))
done

help_output=$(PERL5LIB="$perl5lib" /usr/bin/perl \
  -MDigitalAssets::CLI \
  -e 'exit DigitalAssets::CLI->new()->run(@ARGV)' \
  -- --help 2>&1)
printf '%s\n' "$help_output" | grep -Fqx \
  'usage: labwc-digital-assets-action [--menu-catalog] [--run] <action> <file-or-list>'

